package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g18e69gfvt9c5mw40ykfzvhtjlmur8guhp4zjtav"), 30),
		},
		"Add validator g18e69gfvt9c5mw40ykfzvhtjlmur8guhp4zjtav",
		"Add operator g18e69gfvt9c5mw40ykfzvhtjlmur8guhp4zjtav to the active valset with voting power 30.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}
